import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import Ajv2020 from "ajv/dist/2020";
import { generateConfig } from "../src/generate";
import { sampleProfiles } from "./samples";

// Generated by `sing-box schema` from the official 1.14.3 release (identical to docs/schema.json in its source).
const schema = JSON.parse(readFileSync(new URL("./fixtures/sing-box-1.14.3.schema.json", import.meta.url), "utf8"));
const validate = new Ajv2020({ strict: false, allErrors: true }).compile(schema);

describe("generated configs match the sing-box 1.14.3 JSON schema", () => {
  it.each(sampleProfiles().map((s) => [s.name, s.profile] as const))("%s", (_name, profile) => {
    const ok = validate(generateConfig(profile));
    expect(validate.errors ?? [], JSON.stringify(validate.errors?.slice(0, 3), null, 2)).toEqual([]);
    expect(ok).toBe(true);
  });

  it("catches a misspelled field", () => {
    const config = generateConfig(sampleProfiles()[0].profile) as any;
    config.dns.rules[0].prefered_by = "local";
    expect(validate(config)).toBe(false);
  });
});
